import {T,step,v,n,o,p,f,pow,sub,prime,eq,plus,minus,x,y,t,lines} from '../../../study/math.js';
const M=v('M'),V=v('V'),c=v('c'),Q=sub(v('Q'),v('in')),R=sub(v('Q'),v('out')),ci=sub(c,v('in')),w=sub(v('v'),x),z=sub(v('v'),y);
const tankSteps=[
 step('1. Önce miktarı say','1. Account for amount',M+eq+V+c,'Yoğunluk korunmuş bir miktar değildir. Kirletici miktarı M=Vc üzerinden madde dengesi kurulur.','Concentration is not a conserved amount. Form the material balance using pollutant amount M=Vc.'),
 step('2. Giriş eksi çıkış','2. Inflow minus outflow',prime('M')+eq+Q+ci+minus+R+c,'Tam karışım nedeniyle çıkış yoğunluğu tankın anlık yoğunluğudur; başlangıç yoğunluğu değildir.','Perfect mixing makes outlet concentration equal to the current tank concentration, not its initial concentration.'),
 step('3. Hacim değişimini saklama','3. Keep the changing volume',V+prime('c')+plus+prime('V')+c+eq+Q+ci+minus+R+c,'M=Vc’nin türevinde ürün kuralı gerekir. Debiler farklıysa V sabit sayı gibi türevlenemez.','Differentiating M=Vc requires the product rule. Unequal flows mean V cannot be treated as constant.'),
 step('4. Sadeleştir ve yorumla','4. Simplify and interpret',lines(prime('V')+eq+Q+minus+R,prime('c')+eq+f(Q,V)+p(ci+minus+c)),'Qout açık katsayıdan silinir ama V(t)=V₀+(Qin−Qout)t içinde kalır. Çıkışın fiziksel etkisi kaybolmaz.','Qout cancels as an explicit coefficient but remains in V(t)=V₀+(Qin−Qout)t. Its physical effect remains.'),
 step('5. Birim ve geçerlilik kontrolü','5. Check units and validity',f(Q,V)+eq+f(n(5),n(100))+eq+n('0.05')+v('min⁻¹'),'Q/V zamanın tersidir. Çözümü yalnız V>0 iken kullan; sonlu tankın taşma kapasitesini de ayrıca kontrol et.','Q/V has inverse-time units. Use the solution only for V>0 and check overflow capacity in a finite tank.')
];
const projectileSteps=[
 step('1. Koordinatları seç','1. Choose coordinates',lines(sub(v('F'),x)+eq+minus+v('β')+w,sub(v('F'),y)+eq+minus+v('m')+v('g')+minus+v('β')+z),'Yukarı yön pozitif. Hava direnci her hız bileşenine zıt yönde; yerçekimi yalnız düşey yönde.','Upward is positive. Drag opposes each velocity component; gravity acts vertically.'),
 step('2. Newton yasasını iki yönde yaz','2. Apply Newton in each direction',lines(v('m')+prime('x',2)+eq+minus+v('β')+prime('x'),v('m')+prime('y',2)+eq+minus+v('m')+v('g')+minus+v('β')+prime('y')),'Tek bir skaler denklem iki bileşeni belirlemez. Aynı başlangıç anında konum ve hız bileşenlerini belirt.','One scalar equation cannot determine two components. State initial position and velocity components.'),
 step('3. Kütleye böl ve zaman ölçeğini bul','3. Divide by mass and find a time scale',sub(v('τ'),v('drag'))+eq+f(v('m'),v('β')),'β/m hızın azalma oranını belirler. Aynı β altında daha büyük kütle dirençten daha yavaş etkilenir. β=0 sınırı ayrı alınır.','β/m controls velocity decay. At the same β, larger mass responds more slowly to drag. Take β=0 as a separate limit.'),
 step('4. Dirençsiz sınırı denetle','4. Check the drag-free limit',lines(x+eq+sub(v('v'),n(0))+o('cos')+v('θ')+t,y+eq+sub(v('v'),n(0))+o('sin')+v('θ')+t+minus+f(v('g')+pow(t,n(2)),n(2))),'β=0 yatay ivmeyi sıfırlar, düşey ivme −g kalır. Bu sınır, grafiği ve işaretleri kontrol eder.','At β=0 horizontal acceleration vanishes while vertical acceleration remains −g. This limit checks both the graph and signs.'),
 step('5. Zemin olayını doğru seç','5. Select the landing event',y+o('(')+sub(t,v('land'))+o(')')+eq+n(0),'Başlangıçta y(0)=0 da bir köktür. Uçuş süresi pozitif ikinci köktür; zemin altındaki matematiksel eğri uçuşun parçası değildir.','The initial y(0)=0 is also a root. Flight time is the later positive root; the curve below ground is outside the flight.')
];
export const introductionStudy={title:T('Denklemden önce dengeyi kur.','Build the balance before the equation.'),intro:T('Bir sonucu tahmin et; fiziksel yasayı beş adımda kur; aşağıdaki deneyde aynı varsayımı değiştirerek sınayabilirsin.','Predict a result, build the physical law in five steps, then test the same assumption in the experiment below.'),paths:[
 {title:T('Karışım dengesi','Mixing balance'),prompt:T('Debileri farklı bir tankta c′ neden yalnız giriş debisini açıkça içeriyor?','Why does concentration rate explicitly contain only inflow, even with unequal flows?'),steps:tankSteps,reflection:T('Qout’un iptalini, tanktan kirletici çıkmamasıyla neden karıştıramayız?','Why does cancellation of Qout not mean that no pollutant leaves?')},
 {title:T('Kuvvetten atışa','From force to trajectory'),prompt:T('Direnci kaldırınca hızın iki bileşeni aynı şekilde mi davranır?','Do the two velocity components respond identically when drag is removed?'),steps:projectileSteps,reflection:T('β=0 sınırı ile β/m çok küçük durumunu nasıl ayırırsın?','How do you distinguish β=0 from a very small β/m?')}
],predictions:[
 {id:'tank-outflow',question:T('Çıkış debisi artarsa ilk c′ değişir mi?','Does more outflow change the initial c′?'),context:T('V₀=100 L, Qin=5 L/dk, cin=0,02 ve c₀=0,10 aynı. Yalnız Qout 5’ten 8’e çıkıyor.','Keep V₀=100 L, Qin=5 L/min, cin=0.02 and c₀=0.10. Only Qout changes from 5 to 8.'),choices:T(['İlk hız aynı; sonraki gidiş değişebilir.','İlk yoğunluk azalması doğrudan iki katına çıkar.','Çıkışın hiçbir zaman etkisi yoktur.'],['Initial rate is the same; later behavior can differ.','Initial concentration decay directly doubles.','Outflow never has an effect.']),answer:0,reason:T('İlk anda aynı V₀ vardır; c′(0)=−0,004 dk⁻¹ değişmez. Daha sonra farklı hacim, değişim hızını etkiler.','The initial V₀ is unchanged, so c′(0)=−0.004 min⁻¹ is unchanged. Later, volume differences affect the rate.'),math:prime('c')+p(n(0))+eq+f(n(5),n(100))+p(n('0.02')+minus+n('0.10'))+eq+minus+n('0.004'),try:T('Aşağıdaki tank deneyinde çıkışı değiştir; aynı ilk eğim ile farklı sonraki gidişi karşılaştır.','Change outflow in the tank experiment below and compare initial slope with later behavior.')},
 {id:'projectile-mass',question:T('Dirençsiz atışta kütle iki katına çıkarsa menzil ne olur?','What happens to range if mass doubles without drag?'),context:T('Başlangıç hızı, açı ve g aynı; β=0.','Same launch speed, angle and g; β=0.'),choices:T(['İki katına çıkar.','Değişmez.','Yarıya iner.'],['It doubles.','It stays the same.','It halves.']),answer:1,reason:T('m iki Newton denkleminde de sadeleşir. Bu sonuç yalnız bu varsayımlar altında geçerlidir; β sabitken dirençli atışta β/m değişir.','Mass cancels in both equations. This applies under these assumptions; with fixed nonzero β, changing mass changes β/m.'),math:prime('x',2)+eq+n(0)+o(',')+prime('y',2)+eq+minus+v('g'),try:T('Atış deneyinde önce direnci sıfırla. Sonra direnci açıp aynı kütle karşılaştırmasını yorumla.','Set drag to zero in the projectile experiment. Then restore drag and interpret the mass comparison.')}
]};
export const introductionClinic={examBlueprint:[{step:T('1 · Sistem ve bilinmeyen','1 · System and unknown'),detail:T('Neyi modellediğini, değişkenleri ve yönleri yaz.','State the system, variables and positive directions.')},{step:T('2 · Denge ve koşullar','2 · Balance and conditions'),detail:T('Kuvvet veya madde dengesini kur; başlangıç ve geçerlilik koşullarını ekle.','Build the force or material balance; add initial and validity conditions.')}],examClinic:[
 {badge:T('ÖZGÜN PROBLEM · 10 PUAN','ORIGINAL PROBLEM · 10 POINTS'),title:T('Boşalan tankta model kurma','Model a draining tank'),statement:T('100 L tankta c₀=0,10. Qin=5 L/dk, Qout=8 L/dk ve cin=0,02. M ve c için denklemleri kur, c′(0)’ı bul ve geçerlilik süresini belirt.','A 100 L tank starts at c₀=0.10. Qin=5 L/min, Qout=8 L/min, cin=0.02. Form equations for M and c, find c′(0), and state the validity interval.'),trap:T('Sabit hacim varsayımı burada geçersizdir; yoğunluk değişimi ile miktar değişimi farklı niceliklerdir.','Constant volume is invalid here; concentration rate and amount rate are different quantities.'),steps:[...tankSteps.slice(0,4).map(st=>({...st,label:T(st.label.tr+' (2 puan)',st.label.en+' (2 points)')})),step('5. Sayısal sonuç ve sınır (2 puan)','5. Numerical result and boundary (2 points)',lines(V+eq+n(100)+minus+n(3)+t,prime('c')+p(n(0))+eq+minus+n('0.004'),n(0)+o('≤')+t+o('<')+f(n(100),n(3))),'c′(0)=−0,4 yüzde puan/dk. V>0 için t<33⅓ dk; boşalma anında bu model uygulanmaz.','c′(0)=−0.4 percentage points/min. V>0 requires t<33⅓ min; the model cannot be used at emptying.')]},
 {badge:T('ÖZGÜN PROBLEM · 8 PUAN','ORIGINAL PROBLEM · 8 POINTS'),title:T('Göreli koordinatta zemin zorlaması','Ground forcing in relative coordinates'),statement:T('Mutlak bina konumu x, zemin konumu x₀. Yay ve sönüm kuvvetleri göreli harekete bağlı. y=x−x₀ kullanarak hareket denklemini kur ve x₀=at+b durumunu yorumla.','Let x be absolute building displacement and x₀ ground displacement. Spring and damping forces depend on relative motion. Derive the equation for y=x−x₀ and interpret x₀=at+b.'),trap:T('Verilmiş zemin yer değiştirmesini doğrudan −kx₀ zorlaması diye ekleme; koordinat dönüşümünü ivmede de uygula.','Do not insert −kx₀ as forcing; apply the coordinate transformation to acceleration too.'),steps:[step('1. Göreli hareket (2 puan)','1. Relative motion (2 points)',lines(y+eq+x+minus+sub(x,n(0)),prime('x',2)+eq+prime('y',2)+plus+pow(sub(x,n(0)),o('′′'))),'Mutlak ivme, göreli ivme ile zemin ivmesinin toplamıdır.','Absolute acceleration is the sum of relative and ground acceleration.'),step('2. Newton dengesi (2 puan)','2. Newton balance (2 points)',v('m')+prime('x',2)+eq+minus+v('c')+prime('y')+minus+v('k')+y,'Yay ve sönüm kuvvetleri göreli konum ve hıza bağlıdır.','Spring and damping forces depend on relative position and velocity.'),step('3. Yerine koy (2 puan)','3. Substitute (2 points)',v('m')+prime('y',2)+plus+v('c')+prime('y')+plus+v('k')+y+eq+minus+v('m')+pow(sub(x,n(0)),o('′′')),'Zemin ivmesi etkin zorlamadır.','Ground acceleration is the effective forcing.'),step('4. Sınır durumu (2 puan)','4. Limiting case (2 points)',pow(sub(x,n(0)),o('′′'))+eq+n(0),'Sabit hızlı zemin için sürekli zorlama sıfırdır. Sıfır olmayan başlangıç verileri serbest titreşim doğurabilir.','For constant ground velocity, continuing forcing is zero. Nonzero initial data can still cause free vibration.')]}]};
